import{_ as e,o,c as n,a2 as a}from"./chunks/framework.Di-jvWLj.js";const y=JSON.parse('{"title":"Tools & Tool Errors","description":"","frontmatter":{},"headers":[],"relativePath":"guide/tools.md","filePath":"guide/tools.md","lastUpdated":1792515898000}'),t={name:"guide/tools.md"};function l(r,s,p,c,i,d){return o(),n("div",null,[...s[0]||(s[0]=[a(`<h1 id="tools-tool-errors" tabindex="-1">Tools &amp; Tool Errors <a class="header-anchor" href="#tools-tool-errors" aria-label="Permalink to &quot;Tools &amp; Tool Errors&quot;">​</a></h1><p>chamberu tools are AI SDK tools. Build them with <code>tool()</code> from <code>ai</code>, or with <code>defineTool()</code> when a tool needs the run context (<code>context.run</code>, <code>context.state</code>, <code>context.artifacts</code>; see <a href="/guide/agents#tools-and-their-context">Tools and their context</a>), and pass them to the agent&#39;s <code>tools</code>. chamberu does not wrap or replace them, with one exception: <a href="/guide/effect-tools">effect tools</a> are wrapped so their side effect applies at most once.</p><h2 id="errors-go-back-to-the-model" tabindex="-1">Errors go back to the model <a class="header-anchor" href="#errors-go-back-to-the-model" aria-label="Permalink to &quot;Errors go back to the model&quot;">​</a></h2><p>When a tool throws, the AI SDK turns the error into a tool error result and the model sees it on its next call. It can retry, try something else or give up. The run does not fail, and the step is recorded as a <code>tool</code> step with <code>error: { code, message }</code>.</p><p>The <a href="/guide/budgets">step budget</a> caps retry loops: a model that keeps calling a failing tool runs out of steps and the run fails with <code>BudgetExceeded</code>.</p><h2 id="fataltoolerror-fails-the-run" tabindex="-1">FatalToolError fails the run <a class="header-anchor" href="#fataltoolerror-fails-the-run" aria-label="Permalink to &quot;FatalToolError fails the run&quot;">​</a></h2><p>Throw <code>FatalToolError</code> when continuing makes no sense: a missing credential, a forbidden target, a broken invariant.</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamberu vp-code" tabindex="0"><code><span class="line"><span style="color:#FF7B84;">export</span><span style="color:#FF7B84;"> const</span><span style="color:#E6DFDE;"> reader = defineAgent({</span></span>
<span class="line"><span style="color:#E6DFDE;">    name: </span><span style="color:#E7C58C;">&#39;reader&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    model,</span></span>
<span class="line"><span style="color:#E6DFDE;">    instructions: </span><span style="color:#E7C58C;">&#39;Answer questions about the repository.&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    tools: {</span></span>
<span class="line"><span style="color:#E6DFDE;">        readFile: tool({</span></span>
<span class="line"><span style="color:#E6DFDE;">            description: </span><span style="color:#E7C58C;">&#39;Reads a file of the repository.&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">            inputSchema: z.object({ path: z.string() }),</span></span>
<span class="line"><span style="color:#E6DFDE;">            execute: </span><span style="color:#FF7B84;">async</span><span style="color:#E6DFDE;"> ({ path }) </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> {</span></span>
<span class="line"><span style="color:#FF7B84;">                if</span><span style="color:#E6DFDE;"> (path.startsWith(</span><span style="color:#E7C58C;">&#39;/etc/&#39;</span><span style="color:#E6DFDE;">)) {</span></span>
<span class="line"><span style="color:#958A8B;">                    // fails the whole run with code &#39;FatalToolError&#39;</span></span>
<span class="line"><span style="color:#FF7B84;">                    throw</span><span style="color:#FF7B84;"> new</span><span style="color:#E6DFDE;"> FatalToolError(</span><span style="color:#E7C58C;">\`Refusing to read </span><span style="color:#E6DFDE;">\${</span><span style="color:#E7C58C;">path</span><span style="color:#E6DFDE;">}</span><span style="color:#E7C58C;">.\`</span><span style="color:#E6DFDE;">);</span></span>
<span class="line"><span style="color:#E6DFDE;">                }</span></span>
<span class="line"><span style="color:#958A8B;">                // any other error goes back to the model as a tool error result</span></span>
<span class="line"><span style="color:#FF7B84;">                return</span><span style="color:#E6DFDE;"> readFile(path);</span></span>
<span class="line"><span style="color:#E6DFDE;">            },</span></span>
<span class="line"><span style="color:#E6DFDE;">        }),</span></span>
<span class="line"><span style="color:#E6DFDE;">    },</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span></code></pre></div><p>The run fails with <code>error.code</code> <code>FatalToolError</code>, or the code you pass as the second constructor argument (<code>new FatalToolError(message, &#39;MissingToken&#39;)</code>). The other tool calls of the same step still complete and are recorded before the run settles.</p><p>Infrastructure failures fail the run as well: a store write that throws, or an unknown agent.</p><h2 id="cancellation-inside-tools" tabindex="-1">Cancellation inside tools <a class="header-anchor" href="#cancellation-inside-tools" aria-label="Permalink to &quot;Cancellation inside tools&quot;">​</a></h2><p>Every tool built with <code>defineTool()</code> gets <code>context.run.signal</code> (a factory gets it as <code>run.signal</code>). It aborts on cancel, drain, timeout and a lost lease, and once the execution has ended (so work a tool left running does not outlive it). Pass it to <code>fetch</code>, child processes and other cancellable work so an aborted run stops quickly.</p><h2 id="tools-with-side-effects" tabindex="-1">Tools with side effects <a class="header-anchor" href="#tools-with-side-effects" aria-label="Permalink to &quot;Tools with side effects&quot;">​</a></h2><p>A recovered run repeats the step that was in progress when the process died. A plain tool that posts a comment would post it again. Use <a href="/guide/effect-tools"><code>defineEffectTool()</code></a> for every tool that changes something outside the run.</p><h2 id="restricting-tools-per-invoker" tabindex="-1">Restricting tools per invoker <a class="header-anchor" href="#restricting-tools-per-invoker" aria-label="Permalink to &quot;Restricting tools per invoker&quot;">​</a></h2><p>A run started through <code>@chamberu/http</code> (REST or MCP) carries its <strong>invoker</strong>, <code>run.trigger.invoker</code>: <code>{ id, kind, name?, permissions }</code> of the authenticated principal (<code>kind</code> is the authenticator&#39;s label: <code>staticTokens()</code> sets <code>token</code> and <code>authup()</code> sets <code>authup</code>; <code>oidc()</code> keeps the kind its <code>principal</code> mapper returns, <code>oidc</code> in these docs). Cron and webhook runs have none. An agent&#39;s <code>toolPolicy(toolName, { run })</code> decides per tool whether the run may use it, and a refused tool is not offered to the model at all.</p><p><code>requireToolPermission()</code> is the built-in policy: it offers a tool when the invoker holds <code>tool:&lt;agent&gt;:&lt;tool&gt;</code> (with the usual matching: <code>*</code> alone grants everything, a <code>*</code> segment matches one segment). Runs without an invoker get no tools unless you pass <code>{ withoutInvoker: &#39;allow&#39; }</code>. Wrap it for exceptions:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamberu vp-code" tabindex="0"><code><span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> status = tool({</span></span>
<span class="line"><span style="color:#E6DFDE;">    description: </span><span style="color:#E7C58C;">&#39;Reports the service status.&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    inputSchema: z.object({}),</span></span>
<span class="line"><span style="color:#E6DFDE;">    execute: </span><span style="color:#FF7B84;">async</span><span style="color:#E6DFDE;"> () </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E7C58C;"> &#39;healthy&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span>
<span class="line"></span>
<span class="line"><span style="color:#958A8B;">// defined once; the run context arrives per call</span></span>
<span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> deploy = defineTool({</span></span>
<span class="line"><span style="color:#E6DFDE;">    description: </span><span style="color:#E7C58C;">&#39;Deploys a version.&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    inputSchema: z.object({ version: z.string() }),</span></span>
<span class="line"><span style="color:#E6DFDE;">    execute: </span><span style="color:#FF7B84;">async</span><span style="color:#E6DFDE;"> ({ version }, { context }) </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> {</span></span>
<span class="line"><span style="color:#958A8B;">        // the invoker is a snapshot of who started the run</span></span>
<span class="line"><span style="color:#FF7B84;">        const</span><span style="color:#E6DFDE;"> { invoker } = context.run.trigger;</span></span>
<span class="line"><span style="color:#FF7B84;">        if</span><span style="color:#E6DFDE;"> (</span><span style="color:#FF7B84;">!</span><span style="color:#E6DFDE;">invoker) </span><span style="color:#FF7B84;">throw</span><span style="color:#FF7B84;"> new</span><span style="color:#E6DFDE;"> FatalToolError(</span><span style="color:#E7C58C;">&#39;deploy needs an invoker&#39;</span><span style="color:#E6DFDE;">);</span></span>
<span class="line"><span style="color:#958A8B;">        // aborts on cancel, drain or timeout</span></span>
<span class="line"><span style="color:#FF7B84;">        return</span><span style="color:#E6DFDE;"> deployVersion(version, invoker.id, context.run.signal);</span></span>
<span class="line"><span style="color:#E6DFDE;">    },</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> byPermission = requireToolPermission();</span></span>
<span class="line"><span style="color:#958A8B;">// exceptions wrap the built-in policy: status is open to every invoker</span></span>
<span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> toolPolicy: ToolPolicy = (toolName, ctx) </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> toolName === </span><span style="color:#E7C58C;">&#39;status&#39;</span><span style="color:#FF7B84;"> ||</span><span style="color:#E6DFDE;"> byPermission(toolName, ctx);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FF7B84;">export</span><span style="color:#FF7B84;"> const</span><span style="color:#E6DFDE;"> ops = defineAgent({</span></span>
<span class="line"><span style="color:#E6DFDE;">    name: </span><span style="color:#E7C58C;">&#39;ops&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    model,</span></span>
<span class="line"><span style="color:#E6DFDE;">    instructions: </span><span style="color:#E7C58C;">&#39;Operate the service.&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#958A8B;">    // offers deploy only to invokers holding tool:ops:deploy (or tool:ops:*, or *)</span></span>
<span class="line"><span style="color:#E6DFDE;">    toolPolicy,</span></span>
<span class="line"><span style="color:#E6DFDE;">    tools: { status, deploy },</span></span>
<span class="line"><span style="color:#E6DFDE;">    approvals: {</span></span>
<span class="line"><span style="color:#958A8B;">        // a release manager deploys without asking, everyone else waits for the owner</span></span>
<span class="line"><span style="color:#E6DFDE;">        deploy: (_input, { runtimeContext }) </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> {</span></span>
<span class="line"><span style="color:#FF7B84;">            const</span><span style="color:#E6DFDE;"> { invoker } = runtimeContext.trigger;</span></span>
<span class="line"><span style="color:#FF7B84;">            return</span><span style="color:#E6DFDE;"> invoker </span><span style="color:#FF7B84;">&amp;&amp;</span><span style="color:#E6DFDE;"> hasPermission(invoker.permissions, </span><span style="color:#E7C58C;">&#39;release:manage&#39;</span><span style="color:#E6DFDE;">) ? </span><span style="color:#E7C58C;">&#39;allow&#39;</span><span style="color:#E6DFDE;"> : </span><span style="color:#E7C58C;">&#39;user&#39;</span><span style="color:#E6DFDE;">;</span></span>
<span class="line"><span style="color:#E6DFDE;">        },</span></span>
<span class="line"><span style="color:#E6DFDE;">    },</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span></code></pre></div><ul><li>The policy covers the whole tool set, the generated <a href="/guide/state">state tools</a> included.</li><li>The invoker is a snapshot taken at dispatch. A run keeps it across approvals and restarts, so its tool set stays the same; revoking a grant later does not reach a run that already holds it.</li><li>A model that calls a refused tool anyway gets the AI SDK&#39;s unavailable-tool error as the tool result; the tool step records it with code <code>tool_not_allowed</code>. The run goes on.</li><li>The engine re-checks every call when it executes. An approved call from an older history (e.g. a policy tightened before the approval was answered) gets a <code>ToolNotAllowedError</code> tool error and the run goes on.</li><li>The invoker only ever comes from an authenticator, never from a request body or payload.</li><li>A tool reads the invoker as <code>context.run.trigger.invoker</code>.</li></ul><h2 id="third-party-tools-with-their-own-context" tabindex="-1">Third-party tools with their own context <a class="header-anchor" href="#third-party-tools-with-their-own-context" aria-label="Permalink to &quot;Third-party tools with their own context&quot;">​</a></h2><p>A tool from another library may declare its own <code>contextSchema</code> and expect its context through the AI SDK. Give it one with the agent&#39;s <code>toolsContext</code>, keyed by tool name:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamberu vp-code" tabindex="0"><code><span class="line"><span style="color:#958A8B;">// a tool from another library, with its own context schema</span></span>
<span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> searchTool = tool({</span></span>
<span class="line"><span style="color:#E6DFDE;">    description: </span><span style="color:#E7C58C;">&#39;Searches the web.&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    inputSchema: z.object({ q: z.string() }),</span></span>
<span class="line"><span style="color:#E6DFDE;">    contextSchema: z.object({ apiKey: z.string() }),</span></span>
<span class="line"><span style="color:#E6DFDE;">    execute: </span><span style="color:#FF7B84;">async</span><span style="color:#E6DFDE;"> (input, { context }) </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> search(input.q, context.apiKey),</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FF7B84;">export</span><span style="color:#FF7B84;"> const</span><span style="color:#E6DFDE;"> researcher = defineAgent({</span></span>
<span class="line"><span style="color:#E6DFDE;">    name: </span><span style="color:#E7C58C;">&#39;researcher&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    model,</span></span>
<span class="line"><span style="color:#E6DFDE;">    instructions: </span><span style="color:#E7C58C;">&#39;Research the question in the trigger payload.&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    tools: { search: searchTool },</span></span>
<span class="line"><span style="color:#958A8B;">    // per tool name, passed through unchanged to every call of every run</span></span>
<span class="line"><span style="color:#E6DFDE;">    toolsContext: { search: { apiKey: process.env.SEARCH_KEY </span><span style="color:#FF7B84;">??</span><span style="color:#E7C58C;"> &#39;&#39;</span><span style="color:#E6DFDE;"> } },</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span></code></pre></div><ul><li>chamberu passes each entry unchanged, by reference, to the tool of that name: to every call of every run of the agent, so the value must be safe to share. It is never cloned, validated or stored; the tool&#39;s own <code>contextSchema</code> validates it.</li><li>A tool without any <code>contextSchema</code> gets its entry too (the AI SDK hands it over unvalidated).</li><li>An entry naming a chamberu tool (built with <code>defineTool()</code>/<code>defineEffectTool()</code>, the state tools included) or no tool of the agent is a misconfiguration: with a plain tool set <code>defineAgent()</code> throws <code>InvalidAgentDefinitionError</code>; with a factory (whose set is only known per execution) the run fails with that error (<code>invalid_agent_definition</code>) before any model call. A factory that returns a tool only sometimes must leave its entry out and close over the value instead.</li><li>Without an entry, a tool whose <code>contextSchema</code> requires a value fails the run (the AI SDK validates the context outside its tool-error handling); an optional schema gets <code>undefined</code>.</li><li>An entry the tool&#39;s <code>contextSchema</code> rejects fails the run the same way, with <code>validation_error</code>. The run error names the tool and the failing paths only, never the entry&#39;s value, so a key in it is not stored or served with the run.</li></ul>`,23)])])}const E=e(t,[["render",l]]);export{y as __pageData,E as default};
